WITH ended_lessons AS (SELECT school_uid,course_id,class_id FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND class_status=3 AND school_uid>0 GROUP BY school_uid,course_id,class_id),
course_frame AS (SELECT a.school_uid,a.course_id,a.category_id,COUNT(DISTINCT l.class_id) AS opened_n FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN ended_lessons l ON a.school_uid=l.school_uid AND a.course_id=l.course_id AND a.biz_id=l.class_id WHERE a.dt='2026-09-11' AND a.biz_type=1 AND a.is_deleted=0 AND a.publish_flag=2 AND a.category_id>0 AND a.start_time>=1788537600 AND a.start_time<1789142400 GROUP BY a.school_uid,a.course_id,a.category_id), pa AS (SELECT a.id,a.biz_id,a.school_uid,a.course_id,a.category_id,a.student_total FROM eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a JOIN course_frame f ON a.school_uid=f.school_uid AND a.course_id=f.course_id AND a.category_id=f.category_id WHERE a.dt='2026-09-11' AND a.biz_type=2 AND a.is_deleted=0 AND a.publish_flag=2 AND a.start_time<1789142400 AND (a.end_time=0 OR a.end_time>=1788537600)), hw AS (SELECT a.id,h.homework_id,h.school_uid,h.course_id,h.end_time,h.num,h.cnum,h.rnum FROM pa a JOIN eo_pdviews.ods_ms_eo_oshw_eeo_course_homework_7df_view h ON a.biz_id=h.homework_id AND a.school_uid=h.school_uid AND a.course_id=h.course_id WHERE h.dt='2026-09-11' AND h.is_del=0 AND h.start_time>=1788537600 AND h.start_time<1789142400), reconciled AS (SELECT h.homework_id,h.school_uid,h.course_id,h.end_time,h.num,h.cnum,h.rnum,COUNT(s.stu_homework_id) AS records_n,COUNT(DISTINCT s.student_uid) AS students_n,SUM(CASE WHEN s.status IN (1,2) AND s.is_draft=0 THEN 1 ELSE 0 END) AS submitted_n,SUM(CASE WHEN s.status=2 AND s.is_draft=0 THEN 1 ELSE 0 END) AS reviewed_n FROM hw h LEFT JOIN eo_pdviews.ods_ms_eo_oshw_eeo_course_homework_students_7df_view s ON s.homework_id=h.homework_id AND s.school_uid=h.school_uid AND s.course_id=h.course_id AND s.dt='2026-09-11' AND s.homework_id BETWEEN 47758891 AND 49111062 AND s.is_del=0 WHERE h.end_time>0 AND h.end_time<1789142400 GROUP BY h.homework_id,h.school_uid,h.course_id,h.end_time,h.num,h.cnum,h.rnum) SELECT CASE WHEN records_n=students_n AND records_n=num AND submitted_n=cnum AND reviewed_n=rnum THEN 'reconciled' ELSE 'unreconciled' END AS quality_group,COUNT(1) AS homework_n,SUM(num) AS master_assigned_n,SUM(records_n) AS detail_assigned_n,SUM(cnum) AS master_submitted_n,SUM(submitted_n) AS detail_submitted_n,SUM(rnum) AS master_reviewed_n,SUM(reviewed_n) AS detail_reviewed_n FROM reconciled GROUP BY quality_group ORDER BY quality_group LIMIT 2
